def format_bytes(n):
    if n == 0:
        return "0 Bytes"
    suffixes = ["Bytes", "KB", "MB", "GB", "TB"]
    i = 0
    while n >= 1024 and i < len(suffixes) - 1:
        n /= 1024
        i += 1
    return f"{n:.2f} {suffixes[i]}"'
